using System.Text.Json;
using Neuroset.Application;
using Neuroset.Domain;

namespace Neuroset.Storage;

public sealed class SqliteMemoryStore(SqliteDatabase database) : IMemoryStore
{
    public async Task<IReadOnlyList<MemoryRecord>> ListAsync(MemoryScope? scope=null, Guid? conversationId=null, CancellationToken cancellationToken=default)
    {
        var result=new List<MemoryRecord>(); await using var connection=await database.OpenAsync(cancellationToken).ConfigureAwait(false);
        await using var command=connection.CreateCommand();
        command.CommandText="SELECT Id,Scope,ConversationId,Content,Source,Importance,CreatedAt,LastAccessedAt FROM Memory WHERE ($scope IS NULL OR Scope=$scope) AND ($conversation IS NULL OR ConversationId=$conversation) ORDER BY Importance DESC, LastAccessedAt DESC;";
        command.Parameters.AddWithValue("$scope", scope is null?DBNull.Value:(int)scope.Value); command.Parameters.AddWithValue("$conversation", conversationId is null?DBNull.Value:conversationId.Value.ToString());
        await using var r=await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false); while(await r.ReadAsync(cancellationToken).ConfigureAwait(false)) result.Add(new MemoryRecord{Id=Guid.Parse(r.GetString(0)),Scope=(MemoryScope)r.GetInt32(1),ConversationId=r.IsDBNull(2)?null:Guid.Parse(r.GetString(2)),Content=r.GetString(3),Source=r.GetString(4),Importance=r.GetDouble(5),CreatedAt=DateTimeOffset.Parse(r.GetString(6)),LastAccessedAt=DateTimeOffset.Parse(r.GetString(7))}); return result;
    }
    public async Task SaveAsync(MemoryRecord m,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="INSERT INTO Memory(Id,Scope,ConversationId,Content,Source,Importance,CreatedAt,LastAccessedAt) VALUES($id,$scope,$conversation,$content,$source,$importance,$created,$accessed) ON CONFLICT(Id) DO UPDATE SET Content=excluded.Content,Source=excluded.Source,Importance=excluded.Importance,LastAccessedAt=excluded.LastAccessedAt;";q.Parameters.AddWithValue("$id",m.Id.ToString());q.Parameters.AddWithValue("$scope",(int)m.Scope);q.Parameters.AddWithValue("$conversation",(object?)m.ConversationId?.ToString()??DBNull.Value);q.Parameters.AddWithValue("$content",m.Content);q.Parameters.AddWithValue("$source",m.Source);q.Parameters.AddWithValue("$importance",m.Importance);q.Parameters.AddWithValue("$created",m.CreatedAt.ToString("O"));q.Parameters.AddWithValue("$accessed",m.LastAccessedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    public Task DeleteAsync(Guid id,CancellationToken ct=default)=>ExecuteAsync("DELETE FROM Memory WHERE Id=$id;",("$id",id.ToString()),ct);
    public Task ClearAsync(MemoryScope? scope=null,CancellationToken ct=default)=>scope is null?ExecuteAsync("DELETE FROM Memory;",null,ct):ExecuteAsync("DELETE FROM Memory WHERE Scope=$scope;",("$scope",(int)scope.Value),ct);
    private async Task ExecuteAsync(string sql,(string,object)? parameter,CancellationToken ct){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText=sql;if(parameter is { } p)q.Parameters.AddWithValue(p.Item1,p.Item2);await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
}

public sealed class SqliteScheduledTaskRepository(SqliteDatabase database) : IScheduledTaskRepository
{
    public async Task<IReadOnlyList<ScheduledTaskDefinition>> ListAsync(CancellationToken ct=default){var list=new List<ScheduledTaskDefinition>();await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="SELECT DefinitionJson FROM ScheduledTasks ORDER BY NextRunAt;";await using var r=await q.ExecuteReaderAsync(ct).ConfigureAwait(false);while(await r.ReadAsync(ct).ConfigureAwait(false)){var item=JsonSerializer.Deserialize<ScheduledTaskDefinition>(r.GetString(0),DomainJson.Options);if(item is not null)list.Add(item);}return list;}
    public async Task SaveAsync(ScheduledTaskDefinition t,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="INSERT INTO ScheduledTasks(Id,DefinitionJson,NextRunAt,IsEnabled,UpdatedAt) VALUES($id,$json,$next,$enabled,$updated) ON CONFLICT(Id) DO UPDATE SET DefinitionJson=excluded.DefinitionJson,NextRunAt=excluded.NextRunAt,IsEnabled=excluded.IsEnabled,UpdatedAt=excluded.UpdatedAt;";q.Parameters.AddWithValue("$id",t.Id.ToString());q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(t,DomainJson.Options));q.Parameters.AddWithValue("$next",(object?)t.NextRunAt?.ToString("O")??DBNull.Value);q.Parameters.AddWithValue("$enabled",t.IsEnabled);q.Parameters.AddWithValue("$updated",DateTimeOffset.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    public async Task DeleteAsync(Guid id,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="DELETE FROM ScheduledTasks WHERE Id=$id;";q.Parameters.AddWithValue("$id",id.ToString());await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
}

public sealed class SqliteToolPermissionRepository(SqliteDatabase database) : IToolPermissionRepository
{
    public async Task<ToolPermissionRule?> FindAsync(string toolName,ToolRisk risk,Guid? conversationId,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="SELECT Id,ToolName,Risk,Policy,ConversationId,ConstraintJson,UpdatedAt FROM ToolPermissions WHERE ToolName=$tool AND Risk=$risk AND (ConversationId=$conversation OR ConversationId IS NULL) ORDER BY ConversationId IS NOT NULL DESC LIMIT 1;";q.Parameters.AddWithValue("$tool",toolName);q.Parameters.AddWithValue("$risk",(int)risk);q.Parameters.AddWithValue("$conversation",(object?)conversationId?.ToString()??DBNull.Value);await using var r=await q.ExecuteReaderAsync(ct).ConfigureAwait(false);return await r.ReadAsync(ct).ConfigureAwait(false)?Read(r):null;}
    public async Task<IReadOnlyList<ToolPermissionRule>> ListAsync(CancellationToken ct=default){var list=new List<ToolPermissionRule>();await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="SELECT Id,ToolName,Risk,Policy,ConversationId,ConstraintJson,UpdatedAt FROM ToolPermissions ORDER BY ToolName,Risk;";await using var r=await q.ExecuteReaderAsync(ct).ConfigureAwait(false);while(await r.ReadAsync(ct).ConfigureAwait(false))list.Add(Read(r));return list;}
    public async Task SaveAsync(ToolPermissionRule p,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="INSERT INTO ToolPermissions(Id,ToolName,Risk,Policy,ConversationId,ConstraintJson,UpdatedAt) VALUES($id,$tool,$risk,$policy,$conversation,$constraint,$updated) ON CONFLICT(Id) DO UPDATE SET Policy=excluded.Policy,ConstraintJson=excluded.ConstraintJson,UpdatedAt=excluded.UpdatedAt;";q.Parameters.AddWithValue("$id",p.Id.ToString());q.Parameters.AddWithValue("$tool",p.ToolName);q.Parameters.AddWithValue("$risk",(int)p.Risk);q.Parameters.AddWithValue("$policy",(int)p.Policy);q.Parameters.AddWithValue("$conversation",(object?)p.ConversationId?.ToString()??DBNull.Value);q.Parameters.AddWithValue("$constraint",(object?)p.ConstraintJson??DBNull.Value);q.Parameters.AddWithValue("$updated",p.UpdatedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    public async Task DeleteAsync(Guid id,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="DELETE FROM ToolPermissions WHERE Id=$id;";q.Parameters.AddWithValue("$id",id.ToString());await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static ToolPermissionRule Read(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(){Id=Guid.Parse(r.GetString(0)),ToolName=r.GetString(1),Risk=(ToolRisk)r.GetInt32(2),Policy=(PermissionPolicy)r.GetInt32(3),ConversationId=r.IsDBNull(4)?null:Guid.Parse(r.GetString(4)),ConstraintJson=r.IsDBNull(5)?null:r.GetString(5),UpdatedAt=DateTimeOffset.Parse(r.GetString(6))};
}

public sealed class SqliteKnowledgeRepository(SqliteDatabase database) : IKnowledgeRepository
{
    public async Task SaveSourceAsync(KnowledgeSource s,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="INSERT INTO KnowledgeSources(Id,Name,LocalPath,MediaType,Sha256,SizeBytes,ChunkCount,Status,Error,CreatedAt,IndexedAt) VALUES($id,$name,$path,$media,$sha,$size,$count,$status,$error,$created,$indexed) ON CONFLICT(Id) DO UPDATE SET Name=excluded.Name,LocalPath=excluded.LocalPath,Sha256=excluded.Sha256,SizeBytes=excluded.SizeBytes,ChunkCount=excluded.ChunkCount,Status=excluded.Status,Error=excluded.Error,IndexedAt=excluded.IndexedAt;";q.Parameters.AddWithValue("$id",s.Id.ToString());q.Parameters.AddWithValue("$name",s.Name);q.Parameters.AddWithValue("$path",s.LocalPath);q.Parameters.AddWithValue("$media",s.MediaType);q.Parameters.AddWithValue("$sha",s.Sha256);q.Parameters.AddWithValue("$size",s.SizeBytes);q.Parameters.AddWithValue("$count",s.ChunkCount);q.Parameters.AddWithValue("$status",s.Status);q.Parameters.AddWithValue("$error",(object?)s.Error??DBNull.Value);q.Parameters.AddWithValue("$created",s.CreatedAt.ToString("O"));q.Parameters.AddWithValue("$indexed",(object?)s.IndexedAt?.ToString("O")??DBNull.Value);await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    public async Task SaveChunksAsync(Guid sourceId,IReadOnlyList<KnowledgeChunk> chunks,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var tx=await c.BeginTransactionAsync(ct).ConfigureAwait(false);await using(var d=c.CreateCommand()){d.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;d.CommandText="DELETE FROM KnowledgeChunks WHERE SourceId=$source;";d.Parameters.AddWithValue("$source",sourceId.ToString());await d.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}foreach(var chunk in chunks){await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="INSERT INTO KnowledgeChunks(Id,SourceId,Ordinal,Content,Embedding,MetadataJson) VALUES($id,$source,$ordinal,$content,$embedding,$metadata);";q.Parameters.AddWithValue("$id",chunk.Id.ToString());q.Parameters.AddWithValue("$source",sourceId.ToString());q.Parameters.AddWithValue("$ordinal",chunk.Ordinal);q.Parameters.AddWithValue("$content",chunk.Content);q.Parameters.Add("$embedding",Microsoft.Data.Sqlite.SqliteType.Blob).Value=ToBytes(chunk.Embedding);q.Parameters.AddWithValue("$metadata",JsonSerializer.Serialize(chunk.Metadata,DomainJson.Options));await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}await tx.CommitAsync(ct).ConfigureAwait(false);}
    public async Task<IReadOnlyList<KnowledgeSource>> ListSourcesAsync(CancellationToken ct=default){var list=new List<KnowledgeSource>();await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="SELECT Id,Name,LocalPath,MediaType,Sha256,SizeBytes,ChunkCount,Status,Error,CreatedAt,IndexedAt FROM KnowledgeSources ORDER BY CreatedAt DESC;";await using var r=await q.ExecuteReaderAsync(ct).ConfigureAwait(false);while(await r.ReadAsync(ct).ConfigureAwait(false))list.Add(new KnowledgeSource{Id=Guid.Parse(r.GetString(0)),Name=r.GetString(1),LocalPath=r.GetString(2),MediaType=r.GetString(3),Sha256=r.GetString(4),SizeBytes=r.GetInt64(5),ChunkCount=r.GetInt32(6),Status=r.GetString(7),Error=r.IsDBNull(8)?null:r.GetString(8),CreatedAt=DateTimeOffset.Parse(r.GetString(9)),IndexedAt=r.IsDBNull(10)?null:DateTimeOffset.Parse(r.GetString(10))});return list;}
    public async Task<IReadOnlyList<KnowledgeChunk>> GetChunksAsync(CancellationToken ct=default){var list=new List<KnowledgeChunk>();await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="SELECT Id,SourceId,Ordinal,Content,Embedding,MetadataJson FROM KnowledgeChunks;";await using var r=await q.ExecuteReaderAsync(ct).ConfigureAwait(false);while(await r.ReadAsync(ct).ConfigureAwait(false))list.Add(new KnowledgeChunk{Id=Guid.Parse(r.GetString(0)),SourceId=Guid.Parse(r.GetString(1)),Ordinal=r.GetInt32(2),Content=r.GetString(3),Embedding=FromBytes((byte[])r[4]),Metadata=JsonSerializer.Deserialize<Dictionary<string,string>>(r.GetString(5),DomainJson.Options)??[]});return list;}
    public async Task DeleteSourceAsync(Guid id,CancellationToken ct=default){await using var c=await database.OpenAsync(ct).ConfigureAwait(false);await using var q=c.CreateCommand();q.CommandText="DELETE FROM KnowledgeSources WHERE Id=$id;";q.Parameters.AddWithValue("$id",id.ToString());await q.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static byte[] ToBytes(float[] values){var bytes=new byte[values.Length*sizeof(float)];Buffer.BlockCopy(values,0,bytes,0,bytes.Length);return bytes;}
    private static float[] FromBytes(byte[] bytes){var values=new float[bytes.Length/sizeof(float)];Buffer.BlockCopy(bytes,0,values,0,bytes.Length);return values;}
}
